{"implementation": "def solve(case):
    payload = case["payload"]
    segments = payload["segments"]
    budget = payload["budget"]

    # Validate required fields
    required_fields = ("name", "importance", "minimum", "capacity")
    for i, seg in enumerate(segments):
        for field in required_fields:
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")
        if seg["minimum"] < 0:
            raise ValueError(f"Segment '{seg['name']}' has negative minimum")
        if seg["capacity"] < seg["minimum"]:
            raise ValueError(f"Segment '{seg['name']}' capacity < minimum")

    if "budget" not in payload:
        raise ValueError("Missing required field 'budget' in payload")

    min_sum = sum(seg["minimum"] for seg in segments)
    cap_sum = sum(seg["capacity"] for seg in segments)

    if budget < min_sum:
        raise ValueError(
            f"Budget {budget} is below minimum quota sum {min_sum}"
        )
    if budget > cap_sum:
        raise ValueError(
            f"Budget {budget} exceeds total capacity {cap_sum}"
        )

    # Initialize every segment at its minimum quota (no mutation of input)
    allocations = [seg["minimum"] for seg in segments]
    remaining = budget - min_sum

    # Greedy coarse budget control:
    # Give one token to the segment maximising importance / (current_alloc + 1).
    # Tie-break by original segment order (lower index wins) -- guaranteed by
    # only updating best_idx on strict improvement.
    while remaining > 0:
        best_idx = -1
        best_score = None

        for i, seg in enumerate(segments):
            if allocations[i] >= seg["capacity"]:
                continue
            # next allocated position is current allocation + 1
            score = seg["importance"] / (allocations[i] + 1)
            if best_score is None or score > best_score:
                best_score = score
                best_idx = i
            # equal score: first (lower index) already recorded; no update

        if best_idx == -1:
            raise ValueError(
                "Infeasible: remaining budget cannot be allocated "
                "(all segments at capacity)"
            )

        allocations[best_idx] += 1
        remaining -= 1

    # Derive aggregate from primitive decisions; preserve source identifiers
    alloc_dict = {
        seg["name"]: allocations[i] for i, seg in enumerate(segments)
    }
    name_mapping = {
        seg["name"]: i for i, seg in enumerate(segments)
    }
    total = sum(allocations)  # computed from returned primitives

    return {
        "allocations": alloc_dict,
        "name_mapping": name_mapping,
        "total": total,
    }
"}
